import{_ as t,o,c as r,ag as a}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"takoform_worker_cron_trigger","description":"Worker Cron Trigger (edge.forms.takoform.com/v1beta2, role attachment).","frontmatter":{"page_title":"takoform_worker_cron_trigger Resource - takoform","subcategory":"Edge Platform Family","description":"Worker Cron Trigger (edge.forms.takoform.com/v1beta2, role attachment)."},"headers":[],"relativePath":"docs/resources/worker_cron_trigger.md","filePath":"docs/resources/worker_cron_trigger.md"}'),i={name:"docs/resources/worker_cron_trigger.md"};function n(s,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="takoform-worker-cron-trigger" tabindex="-1">takoform_worker_cron_trigger <a class="header-anchor" href="#takoform-worker-cron-trigger" aria-label="Permalink to &quot;takoform_worker_cron_trigger&quot;">​</a></h1><p>Attaches one cron schedule to a Module Worker, invoking its scheduled handler at each match. Schedules are interpreted in UTC only; there is no timezone field, so two hosts can never fire the same trigger at different instants and no schedule ever skips or repeats an hour for a daylight-saving transition. The grammar is five fields separated by single spaces — minute 0-59, hour 0-23, day-of-month 1-31, month 1-12, day-of-week 0-6 with 0 Sunday — and each field is a comma-separated list of <code>*</code>, a literal, a range <code>low-high</code>, <code>*/step</code>, or <code>low-high/step</code>. Names and a step on a bare literal are not accepted, and neither is any value outside its field&#39;s own range, an inverted range, or a step outside 1..span. When day-of-month and day-of-week are BOTH restricted the trigger fires on a day either of them selects; when only one is restricted only that one constrains the day. A missed run is not made up: a host that could not fire a match — because it was unavailable, or because the previous invocation was still running — skips it rather than firing late, so a schedule never produces a backlog. At-least-once delivery applies to each match: a handler may be invoked more than once for one matched minute, and it must be idempotent. An uncaught exception in the handler is a failed invocation reported to host diagnostics; it is not retried within the matched minute and it never becomes an HTTP response.</p><p>This is an <code>attachment</code> resource: it connects a parent to inward activation (routes, domains, schedules, queue consumption). Deleting the attachment never deletes the parent.</p><p>This Experimental Form speaks the Host API v1beta1 lane and requires provider v2.1.1 or later. Provider v2.1.1 is Registry-published; release/version.json retains candidate-only descriptor metadata after owner publication. The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="https://takoform.com/examples/resources/takoform_worker_cron_trigger/resource.tf" target="_blank" rel="noreferrer">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>worker</code> (String, required, forces replacement) — Module Worker whose scheduled handler this trigger invokes. Set the name of the target <code>ModuleWorker</code> resource.</li><li><code>cron</code> (String, required) — UTC cron schedule. Five fields separated by single spaces — minute <code>0</code>-<code>59</code>, hour <code>0</code>-<code>23</code>, day-of-month <code>1</code>-<code>31</code>, month <code>1</code>-<code>12</code>, and day-of-week <code>0</code>-<code>6</code> with <code>0</code> Sunday — where each field is a comma-separated list of <code>*</code>, a literal, a range <code>low-high</code>, <code>*/step</code>, or <code>low-high/step</code>. Month and day names, and a step on a bare literal such as <code>5/10</code>, are not accepted. The provider parses the expression at plan time exactly as the host does, so a value outside its field&#39;s range, an inverted range such as <code>5-1</code>, or a step outside <code>1</code>..span is a plan-time error rather than a failed apply. When day-of-month and day-of-week are both restricted the schedule fires on a day either selects.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>update_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>20m</code> / <code>30m</code>).</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes. Updates fence on it. It is also the DELETE fence, because a delete withdraws desired state like any other desired-state mutation.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, new outputs, or a change to another resource this one is rendered from. It is the strong ETag, and it is deliberately NOT the delete fence: a teardown removes dependents first and would otherwise be refused by a revision it moved itself.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — the WHOLE <code>status.outputs</code> document, JSON-serialized. This Form declares no <code>outputSchema</code>, so a conforming host omits <code>status.outputs</code> entirely and this attribute is <code>&quot;{}&quot;</code>. It stays declared because a host may publish a value no contract describes, and an undescribed value must still be reachable rather than silently dropped.</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes an in-place re-apply of the same desired state, which is all a host needs to re-resolve and re-pin every reference. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>WorkerCronTrigger</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_cron_trigger.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_cron_trigger.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_cron_trigger.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com/v1beta2&quot;,&quot;kind&quot;:&quot;WorkerCronTrigger&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p>`,15)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
